INSERT INTO `features` VALUES (1,'Dashboard','DASHBOARD','ADMIN','Dashboard','Business overview','Tenant-scoped counts for locations, categories, vendors and support tickets.',NULL,0,1,NULL,10,1,'2026-10-02 11:44:07',0),(2,'Dev Support','DEV_SUPPORT','ADMIN','Dev Support','Raise tickets to the platform team','Raise and track support tickets with the platform/development team.',NULL,0,1,NULL,20,1,'2026-10-02 11:44:07',0),(3,'Branding & Theme','TENANT_BRANDING','ADMIN','Settings','Logos, colours and theme','Tenant logos, favicon, login background, colours and font for the dashboard and apps.',NULL,0,1,NULL,30,1,'2026-10-02 11:44:07',0),(4,'Admin Users & Permissions','ADMIN_USERS_RBAC','ADMIN','Permissions','Staff logins and module permissions','Create dashboard logins for staff and grant per-module view/add/edit/delete rights.',NULL,0,1,'admin users',40,1,'2026-10-02 11:44:07',0),(5,'Locations','LOCATIONS','ADMIN','Locations','Serviceable cities and areas','Delivery areas the tenant serves, with radius per location.',NULL,1,1,'locations',100,1,'2026-10-02 11:44:07',0),(6,'Categories','CATEGORIES','ADMIN','Categories','Category and sub-category tree','Product category and sub-category taxonomy, per vertical.',NULL,1,1,'categories',110,1,'2026-10-02 11:44:07',0),(7,'Products','PRODUCTS','ADMIN','Products','Product catalogue','Tenant-level product master with images, variants and availability.',6,1,1,'products',120,1,'2026-10-02 11:44:07',0),(8,'Orders','ORDERS','ADMIN','Orders','Order listing and status','Order list, detail view and status transitions.',7,1,1,'orders per month',130,1,'2026-10-02 11:44:07',0),(9,'Customers','CUSTOMERS','ADMIN','Customers','Customer directory','End-customer directory with activation control.',NULL,1,1,'customers',140,1,'2026-10-02 11:44:07',0),(10,'Vendors / Stores','VENDORS','ADMIN','Vendors','Multi-vendor store management','Vendor and store records, commission, active and login status.',NULL,1,1,'vendors',150,1,'2026-10-02 11:44:07',0),(11,'Delivery Slots','DELIVERY_SLOTS','ADMIN','Delivery','Delivery time slots','Configurable delivery time-slot windows.',NULL,1,1,'slots',160,1,'2026-10-02 11:44:07',0),(12,'Delivery Partners','DELIVERY_PARTNERS','ADMIN','Delivery','Courier roster','Delivery agent roster with active and login status.',NULL,1,1,'delivery partners',170,1,'2026-10-02 11:44:07',0),(13,'Charges','CHARGES','ADMIN','Settings','Handling and packing charges','Handling, packing, donation and rain-surge charge configuration.',NULL,1,1,NULL,180,1,'2026-10-02 11:44:07',0),(14,'Online Payments','PAYMENT_GATEWAY','ADMIN','Settings','Accept card, UPI and netbanking','Payment gateway credentials that unlock online payment for the storefront. Cash on delivery needs no feature.',NULL,1,1,NULL,190,1,'2026-10-02 11:44:07',0),(15,'Banners','BANNERS','ADMIN','Marketing','In-app promotional banners','Promotional banners shown in the customer app.',NULL,1,1,'banners',200,1,'2026-10-02 11:44:07',0),(16,'Coupons','COUPONS','ADMIN','Marketing','Discount coupons','Discount coupon creation and management.',NULL,1,1,'active coupons',210,1,'2026-10-02 11:44:07',0),(17,'Notifications','NOTIFICATIONS','ADMIN','Marketing','Push and announcements','Push notifications and announcements to customers.',NULL,1,1,NULL,220,1,'2026-10-02 11:44:07',0),(18,'Vendor Settlements','VENDOR_SETTLEMENTS','ADMIN','Settlements','Vendor payouts','Settlement runs and payout submission for vendors.',10,1,1,NULL,230,1,'2026-10-02 11:44:07',0),(19,'Vendor App Workspace','VENDOR_WORKSPACE','PARTNER_APP','Vendor','Store status and hours','Vendor mobile workspace: online/busy state, weekly holiday and store hours.',10,1,1,NULL,300,1,'2026-10-02 11:44:07',0),(20,'Vendor Order Fulfilment','VENDOR_ORDER_FULFILMENT','PARTNER_APP','Vendor Orders','Accept, prep and hand over orders','Accept/reject, extend prep time, mark ready and confirm handover.',8,1,1,NULL,310,1,'2026-10-02 11:44:07',0),(21,'Vendor Menu Management','VENDOR_MENU_MANAGEMENT','PARTNER_APP','Vendor Menu','Edit items from the app','Vendors edit product availability and details from the mobile app.',7,1,1,NULL,320,1,'2026-10-02 11:44:07',0),(22,'Vendor Coupons','VENDOR_COUPONS','PARTNER_APP','Vendor Coupons','Vendor-run offers','Vendors create and toggle their own coupons.',16,1,1,NULL,330,1,'2026-10-02 11:44:07',0),(23,'Vendor Earnings','VENDOR_EARNINGS','PARTNER_APP','Earnings','Payout reporting in-app','Vendor earnings and settlement statements in the mobile app.',18,1,1,NULL,340,1,'2026-10-02 11:44:07',0),(24,'Delivery App Workspace','DELIVERY_WORKSPACE','PARTNER_APP','Delivery','Courier online state and zones','Courier mobile workspace: online state, zones and shift preferences.',12,1,1,NULL,350,1,'2026-10-02 11:44:07',0),(25,'Delivery Trip Fulfilment','DELIVERY_TRIP_FULFILMENT','PARTNER_APP','Trips','Pickup to delivery flow','Accept requests, reach store, confirm pickup, deliver or fail with OTP.',24,1,1,NULL,360,1,'2026-10-02 11:44:07',0),(26,'Delivery Earnings','DELIVERY_EARNINGS','PARTNER_APP','Earnings','Courier earnings in-app','Weekly courier earnings and settlement statements.',24,1,1,NULL,370,1,'2026-10-02 11:44:07',0),(27,'Partner Notifications','PARTNER_NOTIFICATIONS','PARTNER_APP','Notifications','In-app notification feed','In-app notification feed for vendors and couriers.',NULL,1,1,NULL,380,1,'2026-10-02 11:44:07',0),(28,'Partner App Branding','PARTNER_BRANDING','PARTNER_APP','Branding','Tenant theme in the app','Tenant logos and colours applied to the vendor/courier app.',NULL,1,1,NULL,390,1,'2026-10-02 11:44:07',0),(29,'Partner Push Notifications','PARTNER_PUSH','PARTNER_APP','Notifications','FCM push to partner devices','Device registration and FCM push for vendors and couriers.',NULL,1,1,NULL,400,1,'2026-10-02 11:44:07',0),(30,'Shop Items','SHOP_ITEMS','ADMIN','Products','Per-vendor item catalogue','Per-vendor item catalogue, distinct from the tenant product master. Backend not built.',10,1,0,'items per shop',500,1,'2026-10-02 11:44:07',0),(31,'Product Assignment','PRODUCT_ASSIGNMENT','ADMIN','Products','Assign items to vendors','Assign shop items to vendors and categories. Backend not built.',30,1,0,NULL,510,1,'2026-10-02 11:44:07',0),(32,'Payments & History','PAYMENTS_REPORT','ADMIN','Payments','Vendor payment reporting','Vendor payment totals and history. Backend not built.',NULL,1,0,NULL,520,1,'2026-10-02 11:44:07',0),(33,'COD Settlements','COD_SETTLEMENTS','ADMIN','Payments','Courier cash reconciliation','Cash-on-delivery reconciliation for couriers. Backend not built.',12,1,0,NULL,530,1,'2026-10-02 11:44:07',0),(34,'Website CMS','WEBSITE_CMS','ADMIN','Website Management','Banners, home page, testimonials, footer','Static-website content management. UI exists, backend not built.',NULL,1,0,NULL,540,1,'2026-10-02 11:44:07',0),(35,'Storefront Browsing','PUBLIC_BROWSE','PUBLIC_APP','Catalogue','Browse products and categories','Customer-facing product and category browsing. Public App not built.',NULL,1,0,NULL,600,1,'2026-10-02 11:44:07',0),(36,'Cart & Checkout','PUBLIC_CART_CHECKOUT','PUBLIC_APP','Checkout','Cart, checkout and payment','Customer cart, checkout and payment. Public App not built.',35,1,0,NULL,610,1,'2026-10-02 11:44:07',0),(37,'Storefront Offers','PUBLIC_OFFERS','PUBLIC_APP','Promotions','Show coupons and offers','Surfacing coupons and offers to customers. Public App not built.',16,1,0,NULL,620,1,'2026-10-02 11:44:07',0),(38,'Customer Wallet','PUBLIC_WALLET','PUBLIC_APP','Wallet','Wallet and loyalty','Customer wallet, rewards and referrals. Public App not built.',NULL,1,0,NULL,630,1,'2026-10-02 11:44:07',0),(39,'Ratings & Reviews','PUBLIC_REVIEWS','PUBLIC_APP','Reviews','Customer ratings','Customer ratings and reviews. Public App not built.',NULL,1,0,NULL,640,1,'2026-10-02 11:44:07',0),(40,'Order Tracking','PUBLIC_TRACKING','PUBLIC_APP','Delivery','Live order tracking','Live order and delivery tracking for customers. Public App not built.',25,1,0,NULL,650,1,'2026-10-02 11:44:07',0);
